122: static u32 rev_peek_padded(const RevBits *b, unsigned n) {
123:     u32 v = 0; unsigned i;
124:     for (i = 0; i < n; ++i) if (b->bit_pos+i < b->bit_count) {
125:         size_t q = b->bit_count - 1U - b->bit_pos - i;
126:         v |= (u32)((b->src[q>>3] >> (q&7)) & 1U) << (n-1U-i);
127:     }
128:     return v;
129: }
