131: static int fse_build(FSETable *t, const i16 *norm, unsigned max_symbol,
132:                      unsigned table_log) {
133:     u16 symbols[FSE_MAX_SIZE], next[256];
134:     unsigned size, mask, step, pos, high, s, i, nonzero = 0;
135:     if (table_log < 5 || table_log > FSE_MAX_LOG || max_symbol > 255) return 0;
136:     size = 1U << table_log; mask = size-1U; high = size-1U;
137:     memset(symbols, 0xFF, sizeof(symbols)); memset(next, 0, sizeof(next));
138:     for (s = 0; s <= max_symbol; ++s) {
139:         if (norm[s] < -1) return 0;
140:         if (norm[s] == -1) {
141:             symbols[high--] = (u16)s; next[s] = 1; ++nonzero;
142:         } else if (norm[s] > 0) { next[s] = (u16)norm[s]; ++nonzero; }
143:     }
144:     if (nonzero < 2) return 0;
145:     step = (size >> 1) + (size >> 3) + 3U; pos = 0;
146:     for (s = 0; s <= max_symbol; ++s) for (i = 0; i < (unsigned)(norm[s] > 0 ? norm[s] : 0); ++i) {
147:         if (pos > high || symbols[pos] != 0xFFFFU) return 0;
148:         symbols[pos] = (u16)s;
149:         pos = (pos + step) & mask;
150:         while (pos > high) pos = (pos + step) & mask;
151:     }
152:     if (pos != 0) return 0;
153:     for (i = 0; i < size; ++i) {
154:         u16 sym = symbols[i]; unsigned n, nb;
155:         if (sym == 0xFFFFU || sym > max_symbol) return 0;
156:         n = next[sym]++; if (n == 0) return 0;
157:         nb = table_log - highbit32(n);
158:         t->cell[i].symbol = sym; t->cell[i].nb_bits = (u8)nb;
159:         t->cell[i].baseline = (u16)((n << nb) - size);
160:     }
161:     t->table_log = (u8)table_log; t->max_symbol = (u16)max_symbol;
162:     t->valid = 1; t->is_rle = 0; return 1;
163: }
