165: /* RFC 8878 4.1.1, read forward with variable-width normalized counts. */
166: static int fse_read_table(const u8 **pp, const u8 *end, FSETable *t,
167:                           unsigned max_symbol, unsigned max_log) {
168:     FwdBits b; i16 norm[256]; unsigned log, remain, sym = 0, nonzero = 0;
169:     u32 x;
170:     if (*pp >= end || max_symbol > 255 || max_log > FSE_MAX_LOG) return 0;
171:     memset(norm, 0, sizeof(norm));
172:     b.src = *pp; b.bytes = (size_t)(end-*pp); b.bit_pos = 0; b.error = 0;
173:     if (!fwd_read(&b, 4, &x)) return 0;
174:     log = x + 5U; if (log > max_log || log > FSE_MAX_LOG) return 0;
175:     remain = 1U << log;
176:     while (remain != 0) {
177:         unsigned maxval, bits = 0, short_count, low, value, zeros;
178:         i16 count;
179:         if (sym > max_symbol) return 0;
180:         maxval = remain + 1U;
181:         while ((1U << bits) <= maxval) ++bits;
182:         if (bits == 0 || bits > 20 || !fwd_read(&b, bits-1U, &x)) return 0;
183:         low = x; short_count = (1U << bits) - (maxval + 1U);
184:         if (low < short_count) value = low;
185:         else {
186:             if (!fwd_read(&b, 1, &x)) return 0;
187:             value = low + (x << (bits-1U));
188:             if (x) value -= short_count;
189:         }
190:         if (value > maxval) return 0;
191:         count = (i16)value - 1;
192:         if (count > 0 && (unsigned)count > remain) return 0;
193:         if (count == -1) { --remain; ++nonzero; }
194:         else if (count > 0) { remain -= (unsigned)count; ++nonzero; }
195:         norm[sym++] = count;
196:         if (count == 0) {
197:             zeros = 0;
198:             do { if (!fwd_read(&b, 2, &x)) return 0; zeros += x; } while (x == 3U);
199:             if (zeros > max_symbol + 1U - sym) return 0;
200:             while (zeros--) norm[sym++] = 0;
201:         }
202:     }
203:     if (nonzero < 2 || sym == 0 || !fse_build(t, norm, sym-1U, log)) return 0;
204:     if ((b.bit_pos+7U)/8U > b.bytes) return 0;
205:     *pp += (b.bit_pos+7U)/8U; return 1;
206: }
