212: static int fse_predefined(FSETable *t, int kind) {
213:     if (kind == 0) return fse_build(t, k_ll_default, 35, 6);
214:     if (kind == 1) return fse_build(t, k_of_default, 28, 5);
215:     return fse_build(t, k_ml_default, 52, 6);
