217: static int fse_init(const FSETable *t, RevBits *b, u32 *state) {
218:     if (!t->valid) return 0;
219:     if (t->is_rle) { *state = 0; return 1; }
220:     return rev_read(b, t->table_log, state) && *state < (1U << t->table_log);
221: }
222: static u16 fse_sym(const FSETable *t, u32 state) {
223:     if (t->is_rle) return t->rle_symbol;
224:     return state < (1U << t->table_log) ? t->cell[state].symbol : 0xFFFFU;
225: }
226: static int fse_update(const FSETable *t, RevBits *b, u32 *state) {
227:     const FSECell *c; u32 v;
228:     if (t->is_rle) return 1;
229:     if (*state >= (1U << t->table_log)) return 0;
230:     c = &t->cell[*state];
231:     if (!rev_read(b, c->nb_bits, &v)) return 0;
232:     *state = c->baseline + v;
233:     return *state < (1U << t->table_log);
234: }
