236: /* Weights omit their final nonzero entry.  Complete the Kraft sum and make
237:  * a max-bit lookup table whose high bits match the reverse bit reader. */
238: static int huf_make(HUFTable *h, u8 *weights, unsigned explicit_count) {
239:     unsigned s, w, max_bits; u32 total = 0, rest, next = 0;
240:     if (explicit_count == 0 || explicit_count >= 256) return 0;
241:     for (s = 0; s < explicit_count; ++s) {
242:         if (weights[s] > HUF_MAX_BITS) return 0;
243:         if (weights[s]) total += 1U << (weights[s]-1U);
244:     }
245:     if (total == 0) return 0;
246:     max_bits = highbit32(total) + 1U;
247:     if (max_bits > HUF_MAX_BITS) return 0;
248:     rest = (1U << max_bits) - total;
249:     if (rest == 0 || (rest & (rest-1U)) != 0) return 0;
250:     weights[explicit_count++] = (u8)(highbit32(rest)+1U);
251:     if (weights[explicit_count-1U] > HUF_MAX_BITS) return 0;
252:     memset(h, 0, sizeof(*h));
253:     for (w = 1; w <= max_bits; ++w) {
254:         unsigned len = max_bits + 1U - w, scale = 1U << (max_bits-len);
255:         for (s = 0; s < explicit_count; ++s) if (weights[s] == w) {
256:             unsigned code = next >> (max_bits-len), fill = 1U << (max_bits-len);
257:             unsigned i, first = code << (max_bits-len);
258:             for (i = 0; i < fill; ++i) {
259:                 unsigned index = first+i;
260:                 if (h->cell[index].nb_bits) return 0;
261:                 h->cell[index].symbol = (u8)s; h->cell[index].nb_bits = (u8)len;
262:             }
263:             next += scale;
264:         }
265:     }
266:     if (next != (1U << max_bits)) return 0;
267:     h->max_bits = (u8)max_bits; h->valid = 1; return 1;
268: }
