270: /* Huffman-weight streams contain two interleaved FSE states.  At the tail,
271:  * RFC 8878 permits a state transition to consume implicit zero bits.  Try
272:  * the possible 0/1/2 terminal symbols and accept only a valid Kraft tree. */
273: static int huf_fse_weights(const u8 *src, size_t bytes, const FSETable *t,
274:                            u8 *weights, unsigned *count) {
275:     unsigned terminal;
276:     if (!t->valid || t->is_rle) return 0;
277:     for (terminal = 0; terminal <= 2; ++terminal) {
278:         RevBits b;
279:         u32 state[2];
280:         u8 tmp[256];
281:         unsigned n = 0, turn = 0, extra = terminal;
282:         int stopped = 0;
283:         HUFTable trial;
284:         if (!rev_init(&b, src, bytes) || !fse_init(t, &b, &state[0]) ||
285:             !fse_init(t, &b, &state[1])) continue;
286:         while (n < 255) {
287:             const FSECell *c;
288:             if (state[turn] >= (1U << t->table_log)) break;
289:             c = &t->cell[state[turn]];
290:             if (c->symbol > HUF_MAX_BITS) break;
291:             if (rev_left(&b) < c->nb_bits) { stopped = 1; break; }
292:             tmp[n++] = (u8)c->symbol;
293:             if (!fse_update(t, &b, &state[turn])) break;
294:             turn ^= 1U;
295:             if (rev_left(&b) == 0) { stopped = 1; break; }
296:         }
297:         if (!stopped) continue;
298:         while (extra && n < 255) {
299:             if (state[turn] >= (1U << t->table_log) ||
300:                 t->cell[state[turn]].symbol > HUF_MAX_BITS) { n = 0; break; }
301:             tmp[n++] = (u8)t->cell[state[turn]].symbol;
302:             turn ^= 1U;
303:             --extra;
304:         }
305:         if (n == 0) continue;
306:         memcpy(weights, tmp, n);
307:         if (huf_make(&trial, weights, n)) { *count = n; return 1; }
308:     }
309:     return 0;
310: }
