312: static int huf_read_table(const u8 **pp, const u8 *end, HUFTable *h) {
313:     const u8 *p = *pp;
314:     u8 header, weights[256];
315:     unsigned count;
316:     if (p >= end) return 0;
317:     header = *p++; memset(weights, 0, sizeof(weights));
318:     if (header >= 128) {
319:         unsigned i; size_t packed;
320:         count = (unsigned)header - 127U;
321:         packed = (count + 1U) / 2U;
322:         if (count >= 256 || (size_t)(end-p) < packed) return 0;
323:         for (i = 0; i < count; ++i) {
324:             u8 x = p[i >> 1];
325:             weights[i] = (i & 1U) ? (x & 15U) : (x >> 4);
326:         }
327:         p += packed;
328:         if (!huf_make(h, weights, count)) return 0;
329:     } else {
330:         const u8 *section_end;
331:         FSETable table;
332:         if (header == 0 || (size_t)(end-p) < header) return 0;
333:         section_end = p + header;
334:         if (!fse_read_table(&p, section_end, &table, HUF_MAX_BITS, 6) ||
335:             p >= section_end ||
336:             !huf_fse_weights(p, (size_t)(section_end-p), &table, weights, &count) ||
337:             !huf_make(h, weights, count)) return 0;
338:         p = section_end;
339:     }
340:     *pp = p; return 1;
341: }
