343: static int huf_decode_stream(const HUFTable *h, const u8 *src, size_t bytes,
344:                              u8 *out, size_t count) {
345:     RevBits b; size_t i;
346:     if (!h->valid || !rev_init(&b, src, bytes)) return 0;
347:     for (i = 0; i < count; ++i) {
348:         HUFCell c = h->cell[rev_peek_padded(&b, h->max_bits)];
349:         u32 ignored;
350:         if (c.nb_bits == 0 || c.nb_bits > rev_left(&b) ||
351:             !rev_read(&b, c.nb_bits, &ignored)) return 0;
352:         out[i] = c.symbol;
353:     }
354:     return rev_left(&b) == 0;
355: }
