421: static int resolve_offset(ZDecoder *d, u64 value, size_t ll, u64 *offset) {
422:     u32 used;
423:     if (value > 3) {
424:         if (value-3U > UINT_MAX) return 0;
425:         used = (u32)(value-3U);
426:         d->rep[2] = d->rep[1]; d->rep[1] = d->rep[0]; d->rep[0] = used;
427:     } else if (ll == 0 && value == 3) {
428:         if (d->rep[0] <= 1) return 0;
429:         used = d->rep[0]-1U;
430:         d->rep[2] = d->rep[1]; d->rep[1] = d->rep[0]; d->rep[0] = used;
431:     } else {
432:         unsigned index = ll == 0 ? (unsigned)value : (unsigned)(value-1U);
433:         if (index > 2 || d->rep[index] == 0) return 0;
434:         used = d->rep[index];
435:         while (index) { d->rep[index] = d->rep[index-1U]; --index; }
436:         d->rep[0] = used;
437:     }
438:     *offset = used; return 1;
439: }
