441: static int decode_sequences(ZDecoder *d, const u8 *src, const u8 *end,
442:                             size_t literal_count) {
443:     ZReader r;
444:     u32 first, count, n, ll_state, of_state, ml_state;
445:     u8 modes;
446:     unsigned ll_mode, of_mode, ml_mode;
447:     RevBits bits;
448:     size_t literal_pos = 0;
449:     r.p = src; r.end = end; r.error = 0;
450:     if (!need(&r, 1)) return 0;
451:     first = rd8(&r);
452:     if (first == 0) {
453:         if (r.p != end) return 0;
454:         return emit_bytes(d, d->literals, literal_count);
455:     }
456:     if (first < 128) count = first;
457:     else if (first < 255) count = ((first-128U) << 8) + rd8(&r);
458:     else count = (u32)rd8(&r) + ((u32)rd8(&r) << 8) + 0x7F00U;
459:     if (r.error || count == 0 || !need(&r, 1)) return 0;
460:     modes = rd8(&r); if (modes & 3U) return 0;
461:     ll_mode = modes >> 6; of_mode = (modes >> 4) & 3U; ml_mode = (modes >> 2) & 3U;
462: 
463:     if (ll_mode == SEQ_MODE_PREDEFINED) { if (!fse_predefined(&d->ll, 0)) return 0; }
464:     else if (ll_mode == SEQ_MODE_RLE) {
465:         if (!need(&r, 1)) return 0; fse_set_rle(&d->ll, rd8(&r));
466:         if (d->ll.rle_symbol > 35) return 0;
467:     } else if (ll_mode == SEQ_MODE_FSE) {
468:         if (!fse_read_table(&r.p, r.end, &d->ll, 35, 9)) return 0;
469:     } else if (!d->ll.valid) return 0;
470:     if (of_mode == SEQ_MODE_PREDEFINED) { if (!fse_predefined(&d->of, 1)) return 0; }
471:     else if (of_mode == SEQ_MODE_RLE) {
472:         if (!need(&r, 1)) return 0; fse_set_rle(&d->of, rd8(&r));
473:         if (d->of.rle_symbol > 31) return 0;
474:     } else if (of_mode == SEQ_MODE_FSE) {
475:         if (!fse_read_table(&r.p, r.end, &d->of, 31, 8)) return 0;
476:     } else if (!d->of.valid) return 0;
477:     if (ml_mode == SEQ_MODE_PREDEFINED) { if (!fse_predefined(&d->ml, 2)) return 0; }
478:     else if (ml_mode == SEQ_MODE_RLE) {
479:         if (!need(&r, 1)) return 0; fse_set_rle(&d->ml, rd8(&r));
480:         if (d->ml.rle_symbol > 52) return 0;
481:     } else if (ml_mode == SEQ_MODE_FSE) {
482:         if (!fse_read_table(&r.p, r.end, &d->ml, 52, 9)) return 0;
483:     } else if (!d->ml.valid) return 0;
484:     if (r.error || r.p >= r.end || !rev_init(&bits, r.p, (size_t)(r.end-r.p)) ||
485:         !fse_init(&d->ll, &bits, &ll_state) || !fse_init(&d->of, &bits, &of_state) ||
486:         !fse_init(&d->ml, &bits, &ml_state)) return 0;
487: 
488:     for (n = 0; n < count; ++n) {
489:         u16 ll_code = fse_sym(&d->ll, ll_state), of_code = fse_sym(&d->of, of_state);
490:         u16 ml_code = fse_sym(&d->ml, ml_state);
491:         u32 extra; u64 offset_value, offset; size_t ll, ml;
492:         if (ll_code > 35 || of_code > 31 || ml_code > 52 ||
493:             !rev_read(&bits, of_code, &extra)) return 0;
494:         offset_value = ((u64)1 << of_code) + extra;
495:         if (!ml_value(ml_code, &bits, &ml) || !ll_value(ll_code, &bits, &ll) ||
496:             ll > literal_count-literal_pos || !emit_bytes(d, d->literals+literal_pos, ll)) return 0;
497:         literal_pos += ll;
498:         if (!resolve_offset(d, offset_value, ll, &offset) || !copy_match(d, offset, ml)) return 0;
499:         if (n+1U != count && (!fse_update(&d->ll, &bits, &ll_state) ||
500:             !fse_update(&d->ml, &bits, &ml_state) || !fse_update(&d->of, &bits, &of_state))) return 0;
501:     }
502:     if (rev_left(&bits) != 0) return 0;
503:     return emit_bytes(d, d->literals+literal_pos, literal_count-literal_pos);
504: }
