506: static int decode_literals(ZDecoder *d, const u8 **pp, const u8 *end,
507:                            size_t *literal_count) {
508:     const u8 *p = *pp;
509:     u8 first, type, format;
510:     size_t regen, compressed = 0, header_size;
511:     unsigned streams = 1;
512:     if (p >= end) return 0;
513:     first = p[0]; type = first & 3U; format = (first >> 2) & 3U;
514:     if (type == LITERALS_TYPE_RAW || type == LITERALS_TYPE_RLE) {
515:         if (format == 0 || format == 2) { regen = first >> 3; header_size = 1; }
516:         else if (format == 1) {
517:             if ((size_t)(end-p) < 2) return 0;
518:             regen = (first >> 4) | ((size_t)p[1] << 4); header_size = 2;
519:         } else {
520:             if ((size_t)(end-p) < 3) return 0;
521:             regen = (first >> 4) | ((size_t)p[1] << 4) | ((size_t)p[2] << 12);
522:             header_size = 3;
523:         }
524:         if (regen > BLOCK_SIZE_MAX || (size_t)(end-p) < header_size) return 0;
525:         p += header_size;
526:         if (type == LITERALS_TYPE_RAW) {
527:             if ((size_t)(end-p) < regen) return 0;
528:             memcpy(d->literals, p, regen); p += regen;
529:         } else {
530:             if (p >= end) return 0;
531:             memset(d->literals, *p++, regen);
532:         }
533:     } else {
534:         if (format == 0 || format == 1) {
535:             if ((size_t)(end-p) < 3) return 0;
536:             regen = (first >> 4) | ((size_t)(p[1] & 0x3FU) << 4);
537:             compressed = ((size_t)p[1] >> 6) | ((size_t)p[2] << 2);
538:             header_size = 3; streams = format == 0 ? 1U : 4U;
539:         } else if (format == 2) {
540:             if ((size_t)(end-p) < 4) return 0;
541:             regen = (first >> 4) | ((size_t)p[1] << 4) | ((size_t)(p[2] & 3U) << 12);
542:             compressed = ((size_t)p[2] >> 2) | ((size_t)p[3] << 6);
